async function callSafely(fn, name) {
  try {
    const result = await fn();
    return { tool: name, status: "success", result };
  } catch (err) {
    return { tool: name, status: "error", error: String(err && err.message ? err.message : err) };
  }
}

const outcomes = await Promise.all([
  callSafely(() => tools.writer.note_count(), "note_count"),
  callSafely(() => tools.writer.note_denied(), "note_denied"),
  callSafely(() => tools.writer.note_fail(), "note_fail"),
]);

return outcomes;
